diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..53750ae 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,46 @@ export interface Record {
   warns: readonly string[];
 }

+const classifyConstraint = (text: string): string => {
+  const lower = text.toLowerCase();
+  if (
+    lower.includes("stateful service") ||
+    lower.includes("infrastructure") ||
+    lower.includes("always-on") ||
+    lower.includes("operate") ||
+    lower.includes("operational") ||
+    lower.includes("one more thing to run") ||
+    lower.includes("shared cache") ||
+    lower.includes("managed cache")
+  ) {
+    return "operational-overhead";
+  }
+  return text;
+};
+
 export const project = (records: readonly Record[]): string => {
-  const lines: string[] = [];
+  const seenConstraints = new Map<string, string>();
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of record.ruledOut) {
+      const key = classifyConstraint(entry);
+      if (!seenConstraints.has(key)) {
+        seenConstraints.set(key, `- ruled out: ${entry}`);
+      }
+    }
+    for (const limit of record.limits) {
+      const key = classifyConstraint(limit);
+      if (!seenConstraints.has(key)) {
+        seenConstraints.set(key, `- limit: ${limit}`);
+      }
+    }
+    for (const warn of record.warns) {
+      const key = classifyConstraint(warn);
+      if (!seenConstraints.has(key)) {
+        seenConstraints.set(key, `- warn: ${warn}`);
+      }
+    }
   }
-  return lines.join("\n");
+
+  return Array.from(seenConstraints.values()).join("\n");
 };
